        NumericalParamGlobalForm.setWindowTitle(_translate("NumericalParamGlobalForm", "Form"))
        self.checkBoxIVISSE.setToolTip(_translate("NumericalParamGlobalForm", "<html><head/><body><p><span style=\" font-size:9pt;\">Indicate whether the source terms in transposed gradient and velocity divergence should be taken into account in the momentum equation. In the compressible module, these terms also account for the volume viscosity.</span></p><p><span style=\" font-size:9pt;\">(code_saturne key word: </span><span style=\" font-size:9pt; font-weight:600;\">ivisse</span><span style=\" font-size:9pt;\">)</span></p></body></html>"))
        self.checkBoxIVISSE.setText(_translate("NumericalParamGlobalForm", "Handling of transposed gradient and divergence source terms in momentum equation"))
        self.checkBoxICFGRP.setToolTip(_translate("NumericalParamGlobalForm", "<html><head/><body><p><span style=\" font-size:9pt;\">Choose whether the boundary conditions should take into account the hydrostatic balance.</span></p><p><span style=\" font-size:9pt;\">In the cases where gravity is predominant, taking into account the hydrostatic pressure allows to get rid of the disturbances which may appear near the horizontal walls when the flow is little convective. Otherwise, the pressure condition is calculated from the solution of the one-dimensional Euler equations for a perfect gas near a wall, for the variables normal velocity, density and pressure.</span></p><p><span style=\" font-size:9pt;\">(key word: </span><span style=\" font-size:9pt; font-weight:600;\">icfgrp</span><span style=\" font-size:9pt;\">)</span></p></body></html>"))
        self.checkBoxICFGRP.setText(_translate("NumericalParamGlobalForm", "Hydrostatic equilibrium for pressure at walls"))
        self.checkBoxImprovedPressure.setToolTip(_translate("NumericalParamGlobalForm", "<html><head/><body><p>The improved algorithm (which takes into account the balance between the pressure gradient and the source terms) is strongly recommended in the presence of gravity effects, head losses, or momentum source terms.</p><p>When none of the above is present (so that no external forces are present), the improved algorithm should reduce to the classical algorithm, though it may have a slightly  higher computational cost, and could be more sensitive to tuncation errors.</p><p>When the density effects are important, the choice of the improved algorithm allows to improve the interpolation of the pressure and correct the non-physical velocities which may appear in highly stratified areas or near horizontal walls. The improved algorithm also allows eradicating the velocity oscillations which tend to appear at the frontiers of areas with high head losses.</p><p>(key words: <span style=\" font-weight:600;\">iphydr</span> and <span style=\" font-weight:600;\">icalhy</span>)</p></body></html>"))
        self.checkBoxImprovedPressure.setText(_translate("NumericalParamGlobalForm", "Improved pressure interpolation"))
        self.labelRELAXP.setToolTip(_translate("NumericalParamGlobalForm", "<html><head/><body><p><span style=\" font-size:9pt;\">Define the relaxation coefficient of the pressure, in case of unsteady algorithm. Its default value is 1 for the pressure.</span></p></body></html>"))
        self.labelRELAXP.setText(_translate("NumericalParamGlobalForm", "Relaxation of pressure increase"))
        self.lineEditSRROM.setToolTip(_translate("NumericalParamGlobalForm", "<html><head/><body><p><span style=\" font-size:9pt;\">Define the sub-relaxation coefficient </span><span style=\" font-size:9pt; font-weight:600;\">srrom</span><span style=\" font-size:9pt;\"> for the density, in case of gas combustion, pulverized coal or electric arcs: </span></p><p><span style=\" font-size:9pt; font-weight:600;\">rho</span><span style=\" font-size:9pt; font-weight:600; vertical-align:super;\">n+1</span><span style=\" font-size:9pt; font-weight:600;\"> = srrom * rho</span><span style=\" font-size:9pt; font-weight:600; vertical-align:super;\">n</span><span style=\" font-size:9pt; font-weight:600;\"> + (1-srrom) * rho</span><span style=\" font-size:9pt; font-weight:600; vertical-align:super;\">n+1</span></p><p><span style=\" font-size:9pt;\">(key word: </span><span style=\" font-size:9pt; font-weight:600;\">srrom</span><span style=\" font-size:9pt;\">)</span></p></body></html>"))
        self.checkBoxIPUCOU.setToolTip(_translate("NumericalParamGlobalForm", "<html><head/><body><p><span style=\" font-size:9pt;\">Choose the algorithm for velocity/pressure coupling:<br/>- Standard algorithm (unticked box),<br/>- Reinforced coupling in case of calculation with large time steps (ticked box).</span></p><p><span style=\" font-size:9pt;\">(code_saturne key word: </span><span style=\" font-size:9pt; font-weight:600;\">ipucou</span><span style=\" font-size:9pt;\">)</span></p></body></html>"))
        self.checkBoxIPUCOU.setText(_translate("NumericalParamGlobalForm", "Pseudo-coupled velocity-pressure solver"))
        self.lineEditRELAXP.setToolTip(_translate("NumericalParamGlobalForm", "<html><head/><body><p><span style=\" font-size:9pt;\">Define the relaxation coefficient of the pressure, in case of unsteady algorithm. Its default value is 1 for the pressure.</span></p></body></html>"))
        self.labelSRROM.setToolTip(_translate("NumericalParamGlobalForm", "<html><head/><body><p><span style=\" font-size:9pt;\">Define the sub-relaxation coefficient </span><span style=\" font-size:9pt; font-weight:600;\">SRROM</span><span style=\" font-size:9pt;\"> for the density, in case of gas combustion, pulverized coal or electric arcs: </span></p><p><span style=\" font-size:9pt; font-weight:600;\">rho</span><span style=\" font-size:9pt; font-weight:600; vertical-align:super;\">n+1</span><span style=\" font-size:9pt; font-weight:600;\"> = SRROM * rho</span><span style=\" font-size:9pt; font-weight:600; vertical-align:super;\">n</span><span style=\" font-size:9pt; font-weight:600;\"> + (1-SRROM) * rho</span><span style=\" font-size:9pt; font-weight:600; vertical-align:super;\">n+1</span></p><p><span style=\" font-size:9pt;\">(code_saturne key word: </span><span style=\" font-size:9pt; font-weight:600;\">SRROM</span><span style=\" font-size:9pt;\">)</span></p></body></html>"))
        self.labelSRROM.setText(_translate("NumericalParamGlobalForm", "Relaxation of density"))
        self.labelDensityVar.setToolTip(_translate("NumericalParamGlobalForm", "<html><head/><body><p><span style=\" font-size:9pt;\">Indicate the algorithm to take into account for the density variation in time<br/>- Boussinesq approximation (rho constant expect in the buoyant term<br/>- dilatable steady algorithm (default)<br/>- dilatable unsteady algorithm<br/>- low-Mach algorithm<br/>- algorithm for fire</span></p><p><span style=\" font-size:9pt;\">(code_saturne key word: </span><span style=\" font-size:9pt; font-weight:600;\">idilat</span><span style=\" font-size:9pt;\">)</span></p></body></html>"))
        self.labelDensityVar.setText(_translate("NumericalParamGlobalForm", "Algorithm to take into account the density variation in time"))
        self.comboBoxDensityVar.setToolTip(_translate("NumericalParamGlobalForm", "<html><head/><body><p><span style=\" font-size:9pt;\">Indicate the algorithm to take into account for the density variation in time<br/>- Boussinesq approximation (rho constant expect in the buoyant term<br/>- dilatable steady algorithm (default)<br/>- dilatable unsteady algorithm<br/>- low-Mach algorithm<br/>- algorithm for fire</span></p><p><span style=\" font-size:9pt;\">(code_saturne key word: </span><span style=\" font-size:9pt; font-weight:600;\">idilat</span><span style=\" font-size:9pt;\">)</span></p></body></html>"))
        self.groupBoxGradient.setToolTip(_translate("NumericalParamGlobalForm", "<html><head/><body><p><span style=\" font-size:9pt;\">Define global numerical parameters for the calculation.</span></p></body></html>"))
        self.comboBoxGradientType.setToolTip(_translate("NumericalParamGlobalForm", "<html><head/><body><p><span style=\" font-size:9pt;\">Indicate the global gradient reconstruction method (one method for all the variables):<br/>- Green\'s theorem with iterative handling of the non-orthogonalities,<br/>- Least squares method<br/>- Green\'s theorem using face values based on least-squares gradient</span></p></body></html>"))
        self.labelGradientType.setToolTip(_translate("NumericalParamGlobalForm", "<html><head/><body><p><span style=\" font-size:9pt;\">Indicate the global gradient reconstruction method (one method for all the variables):<br/>- Green\'s theorem with iterative handling of the non-orthogonalities,<br/>- Least squares method<br/>- Green\'s theorem using face values based on least-squares gradient</span></p></body></html>"))
        self.labelGradientType.setText(_translate("NumericalParamGlobalForm", "Gradient reconstruction type"))
        self.comboBoxExtNeighbors.setToolTip(_translate("NumericalParamGlobalForm", "<html><head/><body><p><span style=\" font-size:9pt;\">Stencil used for least squares<br/>- face-neighbor cells<br/>- extended neighborhood (cells which share a vertex with the treated cell),<br/>- partial extended neighborhood (all face neighbours plus the extended neighbourhood cells that are connected to a face where the non-orthogonality angle is larger than a certain parameter),</span></p></body></html>"))
        self.labelExtNeighbors.setText(_translate("NumericalParamGlobalForm", "Extended cell neighbors"))
